<?php require_once __DIR__.'/../../config/app.php';requireLogin();$pageTitle='Products';$pageSubtitle='Data Products koperasi sekolah';$isAdmin=(authUser()['role']==='admin');$success=flash('success');$stmt=$pdo->query('SELECT * FROM products ORDER BY product_id DESC');$rows=$stmt->fetchAll(); ?>
<!DOCTYPE html><html lang="id"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Products - Koperasi Sekolah</title><link rel="stylesheet" href="/styles/products/index.css"></head><body><div class="layout"><?php require __DIR__.'/../../components/admin/sidebar.php';?><main class="main"><?php require __DIR__.'/../../components/admin/topbar.php';?><section class="content"><div class="toolbar"><div class="page-heading"><h2>Data Products</h2><p>Daftar products koperasi sekolah.</p></div><?php if($isAdmin):?><a class="btn btn-primary" href="create.php">+ Tambah Product</a><?php endif?></div><?php if($success):?><div class="alert alert-success"><?=e($success)?></div><?php endif?><div class="card"><table><thead><tr><th>Kode Produk</th><th>Nama Produk</th><th>Kategori</th><th>Satuan</th><th>Harga</th><th>Stok</th><th>Tanggal Masuk</th><th>Deskripsi</th><?php if($isAdmin):?><th>Aksi</th><?php endif?></tr></thead><tbody><?php if(!$rows):?><tr><td class="empty" colspan="9">Belum ada data products.</td></tr><?php else:foreach($rows as $row):?><tr><td><?= e($row['product_code']) ?></td><td><?= e($row['product_name']) ?></td><td><?= e($row['category']) ?></td><td><?= e($row['unit']) ?></td><td><?= e($row['price']) ?></td><td><?= e($row['stock']) ?></td><td><?= e($row['entry_date']) ?></td><td><?= e($row['description']) ?></td><?php if($isAdmin):?><td class="actions"><a href="edit.php?id=<?= (int)$row['product_id'] ?>">Edit</a><a class="delete" href="/actions/products/destroy.php?id=<?= (int)$row['product_id'] ?>" onclick="return confirm('Yakin ingin menghapus data ini?')">Hapus</a></td><?php endif?></tr><?php endforeach;endif?></tbody></table></div></section></main></div></body></html>